// 0.57.33 - helper requireCronSecret
export function requireCronSecret(req: Request): Response | null {
  const expected = Deno.env.get("CRON_SECRET");

  if (!expected) {
    // Fail-secure : si pas de secret configuré, on refuse tout
    return new Response(
      JSON.stringify({ error: "CRON_SECRET non configuré" }),
      { status: 500, headers: { ... } }
    );
  }

  const provided = req.headers.get("x-cron-secret") || "";

  // Comparaison constant-time (anti timing-attacks)
  if (provided.length !== expected.length) {
    return new Response(
      JSON.stringify({ error: "CRON secret invalide" }),
      { status: 401, headers: { ... } }
    );
  }
  let mismatch = 0;
  for (let i = 0; i < provided.length; i++) {
    mismatch |= provided.charCodeAt(i) ^ expected.charCodeAt(i);
  }
  if (mismatch !== 0) {
    return new Response(...);  // 401
  }

  return null;  // OK, secret correct
}

