    let mounted = true;
    const controller = new AbortController();
    const ctx = {
      isMounted: () => mounted,
      signal: controller.signal,
    };

    (async () => {
      try {
        await asyncFn(ctx);
      } catch (e) {
        if (!mounted) return;  // ignore les erreurs après démontage
