function highlightCode(code, lang) {
  let html = escapeHtml(code);

  // Commentaires
  if (lang === "sql") {
    html = html.replace(/(--[^\n]*)/g,
      '<span style="color:#7a8a9a;font-style:italic">$1</span>');
  } else {
    html = html.replace(/(\/\/[^\n]*)/g,
      '<span style="color:#7a8a9a;font-style:italic">$1</span>');
  }

  // Strings
  html = html.replace(/(['"`])((?:\\.|(?!\1).)*)\1/g,
    (m) => `<span style="color:#bfa9e0">${m}</span>`);

  // Mots-clés selon langage
  const keywords = lang === "sql"
    ? ["select", "from", "where", "create", "function", ...]
    : ["const", "let", "function", "return", "async", "await", ...];
  const kwRegex = new RegExp(`\\b(${keywords.join("|")})\\b`, "g");
  html = html.replace(kwRegex,
    '<span style="color:#7CC8C8;font-weight:600">$1</span>');

  // Nombres
  html = html.replace(/\b(\d+(\.\d+)?)\b/g,
    '<span style="color:#EF9F27">$1</span>');

  return html;
}

